INSERT INTO product_groups (id, kind, brand_id, name, description_lines, sort_order) VALUES
  ('c513eabc-4c28-58c5-b2ca-c8cd821f8292', 'imported', (SELECT id FROM brands WHERE code = 'LG'), 'VRF System Condensing Units (Outdoor Unit)', '{}'::text[], 1),
  ('9bad5e1f-5ea5-59cb-a13e-59e880ea86f5', 'imported', (SELECT id FROM brands WHERE code = 'LG'), 'VRF System Evaporating Units (Indoor Unit)', '{}'::text[], 2),
  ('0cdc2ff5-2786-5cfd-aa12-9a59a8231956', 'imported', (SELECT id FROM brands WHERE code = 'LG'), 'Remote Controller', '{}'::text[], 3),
  ('f76a4785-b7e7-59f3-b63c-2758153a54c4', 'imported', (SELECT id FROM brands WHERE code = 'LG'), 'Centralized control system', '{}'::text[], 4),
  ('027dfc0c-c8b2-5c7e-8522-978eac2a05d2', 'imported', (SELECT id FROM brands WHERE code = 'LG'), 'Freight', '{}'::text[], 5),
  ('d2752fd4-36f5-5c59-9a76-8a2749622ca5', 'imported', (SELECT id FROM brands WHERE code = 'DAIKIN'), 'VRV A System Condensing Units (Outdoor unit)', ARRAY['Variable Refrigerant Volume (VRV A) units having cooling capacities base on indoor temperature of 27°CDB, 19.5°WB and outdoor temp. of 35.0°CDB. Heating: Indoor temp. of 20°CDB, and outdoor temp. of 7°CDB, 6°CWB. Each unit shall be Modular type complete with DC Scroll Compressor, DX Condenser with Copper tube and Aluminum Fins. Condenser Fan with Fan guard, Y-shapped RefNet joints, complete in all respect. The unit shall operate when supplied with 400±10% V / 50hz / 3 Ph Electric power. The Condensing Units shall have Variable Frequency Drive Mechanism with necessary components.','The supply includes all accessories to complete VRV A mechanism.']::text[], 1),
  ('ff6d4dc3-35df-57f3-856e-e65f4b9c1897', 'imported', (SELECT id FROM brands WHERE code = 'DAIKIN'), 'VRV A System Evaporating Units (Indoor Unit)', ARRAY['Evaporating units having cooling capacities base on indoor temperature of 27°CDB, 19.5°WB and outdoor temp. of 35.0°CDB. Heating: Indoor temp. of 20°CDB, and outdoor temp. of 7°CDB, 6°CWB. Each unit shall be operated with Variable refrigerant Volume (VRV A) outdoor units. Evaporating Units shall have refrigerant control valve (EXV) washable filter, fan speed controller etc. complete in all respect. Vent port shall be built in inside the unit. The unit shall operate when supplied with 220±10% V / 50hz / 1 Ph Electric power.']::text[], 2),
  ('6ced5b71-5b59-595a-87c3-186349416674', 'imported', (SELECT id FROM brands WHERE code = 'DAIKIN'), 'Centralised Control Systems', ARRAY['The user-friendly controller already features colors, multilingual function, and icons in the display for ease of understanding; now, further convenience has been added. New communication capabilities enable centralized control via a Web browser and the sending of e-mail alerts on system operation. A wide variety of control methods can be accommodated, permitting administrators to monitor and operate the system even when they are away from the controller.']::text[], 3),
  ('55f36b54-ff04-5f91-ab4f-c8b9f36ac799', 'imported', (SELECT id FROM brands WHERE code = 'DAIKIN'), 'Ref Net (Distributor / Y-pipe / Branch pipe)', ARRAY['The REFNET joint both reduces the amount of work involved in installation and increases the reliability of the system.']::text[], 4),
  ('53b87fe3-66ec-5811-a051-b36fb144dfc4', 'imported', (SELECT id FROM brands WHERE code = 'DAIKIN'), 'Freight', '{}'::text[], 5),
  ('e9dc50b7-c15b-536b-bba1-90de5ec82b6a', 'imported', (SELECT id FROM brands WHERE code = 'DB'), 'VRF System Condensing Units (Out door unit)', ARRAY['Variable Refrigerant Flow (VRF) units having cooling capacities as mentioned below when air entering the coil at 780 DB / 66.50F WB. And leaving the coil at 550F DB 54.60F WB. Each unit shall be Modular Type complete with Multi Digital Scroll Compressor, DX Condenser with Copper tube and Aluminum Fins. Condenser Fan with Fan guard, Y-shaped RefNet joints, complete in all respect. The unit shall operate when supplied with 400±10% V / 50hz / 3 Ph Electric power. The Condensing Units shall have Variable Frequency Drive Mechanism with necessary components.','The supply includes all accessories to complete VRF mechanism.']::text[], 1),
  ('f6272d73-11aa-524e-a7db-1e41a718e61f', 'imported', (SELECT id FROM brands WHERE code = 'DB'), 'VRF System Evaporating Units (Indoor Unit)', ARRAY['Evaporating units having cooling capacities as mentioned below when air entering the coil at 780 DB / 66.50F WB. And leaving the coil at 550F DB 54.60F WB. Each unit shall be operated with Variable refrigerant Flow (VRF) outdoor units. Evaporating Units shall have refrigerant control valve (EXV) washable filter, fan speed controller etc. complete in all respect. Vent port shall be built in inside the unit. The unit shall operate when supplied with 220±10% V / 50hz / 1 Ph Electric power.']::text[], 2),
  ('d35c3458-0ec1-5274-8142-aecb3f3819d4', 'imported', (SELECT id FROM brands WHERE code = 'DB'), 'Remote Controller', '{}'::text[], 3),
  ('85ce6d95-76f0-5523-bb2d-8fea1edd10ce', 'imported', (SELECT id FROM brands WHERE code = 'DB'), 'Centralized control system', ARRAY['The user-friendly controller already features colors, multilingual function, and icons in the display for ease of understanding; now, further convenience has been added. A wide variety of control methods can be accommodated, permitting administrators to monitor and operate the system even when they are away from the controller.']::text[], 4),
  ('60f60e25-2146-5779-aeab-d1a97e42e765', 'imported', (SELECT id FROM brands WHERE code = 'DB'), 'Freight', '{}'::text[], 5),
  ('6f29ad75-12d9-543f-a21a-a8d0ef7f3df9', 'local', NULL, 'Refrigerant piping: Coil pipe', ARRAY['Brand : Coppertech / Bangladesh','For Liquid & Suction line pipe connection with Indoor & Outdoor unit.']::text[], 1),
